// The key must be STABLE across retries and UNIQUE per real request.
//
// Good keys: an upstream event ID, an order ID, a provider message ID.
// Bad keys: a timestamp, a random value, an execution ID — all three change
// on retry, so every retry looks like a brand new request and the guard
// silently stops guarding.
//
// No natural ID? Hash the meaningful fields instead.
const crypto = require('crypto');

return $input.all().map((item) => {
  const body = item.json.body ?? item.json;

  const naturalId = body.event_id ?? body.order_id ?? body.message_id ?? null;

  const key = naturalId
    ? String(naturalId)
    : crypto
        .createHash('sha256')
        .update(JSON.stringify({ to: body.to, amount: body.amount, ref: body.reference }))
        .digest('hex')
        .slice(0, 32);

  return { json: { ...body, idempotency_key: key, keyedOn: naturalId ? 'natural id' : 'field hash' } };
});
